<?php require_once __DIR__.'/../includes/bootstrap.php'; if(admin_logged_in()) redirect('/admin/dashboard.php'); $title='Management Sign In'; $errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){$username=trim($_POST['username']??'');$pass=$_POST['password']??'';$s=$pdo->prepare('SELECT * FROM users WHERE LOWER(username)=LOWER(?) LIMIT 1');$s->execute([$username]);$u=$s->fetch();if($u&&password_verify($pass,$u['password_hash'])&&in_array($u['role'],['Admin','Staff'],true)){$pdo->prepare('UPDATE users SET is_super_admin=CASE WHEN username=\'SHADRACK OTUMA\' THEN 1 ELSE is_super_admin END WHERE user_id=?')->execute([$u['user_id']]);$_SESSION['admin_id']=(int)$u['user_id'];$_SESSION['admin_role']=$u['role'];$_SESSION['admin_username']=$u['username'];$_SESSION['is_super_admin']=(int)$u['is_super_admin']===1 || strcasecmp($u['username'],'SHADRACK OTUMA')===0;$_SESSION['user_id']=(int)$u['user_id'];$_SESSION['username']=$u['username'];$_SESSION['role']=$u['role'];redirect('/admin/dashboard.php');}$errors[]='Not authorised. Only an authorised administrator or staff account can access management.';}
